import {postCPIOrder} from '@api-integration-aws/core/services';
import {formatResponse} from '@smart/feature-app/node';
import {ApiHandler} from 'sst/node/api';
import {middyfy} from '../../middleware/middy';
import {parseEvent} from '../../utils/parse-event';
import {PostOrderBodySchema} from './schema';

const handler = ApiHandler(async (event) => {
  const parsedEvent = parseEvent(event, {
    BodySchema: PostOrderBodySchema,
  });

  const {bodyData} = parsedEvent;

  const body = bodyData.map((item) => {
    return {
      po: item.Name,
      pn18: item.PN18__c,
      poWeek: item.PO_Week__c,
      quantity: item.Quantity__c,
      marketCode: item.Market_Code__c,
      productionDate: item.Requested_Production_Date__c,
      b2bFlag: item.B2B__c,
      advanceFlag: item.Advance__c,
      isurgentFlag: item.Is_Urgent__c,
      priority: item.Priority__c,
    };
  });

  const response = await postCPIOrder({
    messageHeader: {
      messageContent: body,
    },
  });

  return formatResponse(200, {
    'code': 200,
    'info': `SUCCESS`,
    'response-data': response.Responses.SPTResponse,
  });
});

export const main = middyfy(handler);

